  "plans.eyebrow": "Các gói & tính năng",
  "plans.title": "So sánh các gói StockHaven",
  "plans.intro": "Một tài khoản, dù bạn chọn gói nào — Business bao gồm tối đa năm doanh nghiệp. Giá là hàng tháng tính bằng đô la Mỹ, và khách hàng mới trên trang web đủ điều kiện có thể nhận một bản dùng thử bảy ngày cho cả Essentials và Business. Việc nâng cấp một đăng ký Essentials hiện có lên Business không khởi động lại bản dùng thử và không tạo thêm bản dùng thử miễn phí khác. Giá gói trên trang web chưa bao gồm thuế áp dụng, nếu có. Khoản phí chính xác của bạn sẽ được hiển thị trước khi bạn ủy quyền đăng ký.",
