  "exports.createBusinessFirst": "Hãy tạo một doanh nghiệp trước — bản xuất thuộc về một doanh nghiệp, không thuộc về ứng dụng.",
  "exports.lockedTitle": "Xuất CSV và Excel là tính năng của Business",
  "exports.lockedDesc": "Không gian làm việc của bạn đang dùng gói Essentials. Business bổ sung xuất CSV và Excel, định giá tồn kho, sản phẩm và nhân viên không giới hạn, nhà cung cấp, mua hàng và gói sản phẩm.",
  "exports.seeBusiness": "Xem Business bao gồm những gì",
  "exports.whatTheseAre": "Các tệp này là gì",
  "exports.about1": "Mọi bộ dữ liệu đều có dạng CSV hoặc sổ làm việc Excel thực thụ (.xlsx) — sổ làm việc tồn kho đầy đủ chỉ có dạng Excel, với mỗi bộ dữ liệu trên một trang tính riêng. Tệp CSV mở được trong Excel, Numbers, Google Sheets và hầu hết các ứng dụng quản lý kho. Văn bản UTF-8, dấu phẩy được đặt trong ngoặc kép, ngắt dòng trong ghi chú và số 0 ở đầu mã đều được giữ nguyên, và các ô bắt đầu giống công thức sẽ được vô hiệu hóa để bảng tính mở chúng dưới dạng văn bản.",
  "exports.about2": "Trong tệp Excel, SKU, UPC, ISBN và mã vạch là ô văn bản — không bao giờ ở dạng ký hiệu khoa học và không bao giờ bị cắt số 0 — với chiều rộng cột, bộ lọc tiêu đề và định dạng tiền tệ hoặc số lượng được áp dụng. Sổ làm việc tồn kho đầy đủ giữ sản phẩm, mức tồn kho, địa điểm và biến động trên các trang tính riêng biệt.",
  "exports.about3": "Các bản xuất rất lớn sẽ dừng ở 20.000 hàng cho mỗi bộ dữ liệu — khi điều đó xảy ra, tên tệp sẽ ghi rõ (truncated-20000), để một tệp một phần không bao giờ bị nhầm là đầy đủ.",
  "exports.about4": "Bản sao lưu là bản chụp dữ liệu của bạn, không phải khôi phục bằng một cú nhấp. Việc khôi phục là công việc thủ công, cần xem xét trước, vì vậy hãy giữ tệp ở nơi an toàn — hiện chưa có gì trong ứng dụng có thể tái tạo một doanh nghiệp đã xóa từ tệp này. Mã ứng dụng và bản sao lưu nền tảng Base44 được xử lý riêng với các tệp này.",
  "exports.about5": "Ảnh và tệp đính kèm được liệt kê dưới dạng liên kết đã lưu của chúng — bản thân các tệp hình ảnh không được đóng gói vào bản tải xuống.",
  "exports.backupTitle": "Sao lưu đầy đủ",
  "exports.backupDesc": "Một tệp chứa sản phẩm, địa điểm, mức tồn kho, sổ cái biến động đầy đủ, nhà cung cấp, mua hàng, đơn hàng, hàng trả lại, kiểm kê và danh sách niêm yết của doanh nghiệp này — cùng với cài đặt hồ sơ của nó. Hãy giữ tệp ở nơi bạn kiểm soát.",
  "exports.backupIncludes1": "Sản phẩm, mã, chi phí và ghi chú",
  "exports.backupIncludes2": "Địa điểm và số lượng theo từng địa điểm",
