  "reports.footnote": "Doanh số bán hàng dùng giá bán lẻ hiện tại của mỗi sản phẩm, phiếu nhập dùng chi phí được ghi khi hàng đến, và tổn thất dùng chi phí đơn vị hiện tại. Tiền bị thiếu không bao giờ được coi là 0 — hãy để trống một con số cho đến khi biết rõ. Báo cáo là một chế độ xem, không phải một tài liệu: không có gì được ghi vào hồ sơ của bạn khi bạn chạy một báo cáo.",
