  "payroll.dd.steps.body": "1. Bạn cần một tài khoản ngân hàng doanh nghiệp có thể gửi thanh toán ACH. 2. Thu thập biểu mẫu ủy quyền đã ký từ từng thành viên trong nhóm — một tấm séc đã hủy giúp xác minh các con số. 3. Gửi bảng lương 2-3 ngày làm việc trước ngày trả lương để tiền đến đúng hạn. 4. Hầu hết các tiểu bang yêu cầu sự đồng ý bằng văn bản của thành viên trong nhóm. Ứng dụng này thu thập các biểu mẫu và hướng dẫn bạn qua từng bước — việc thực sự gửi tiền diễn ra qua ngân hàng của riêng bạn.",
