  "training.module.training": "Đào tạo",
  "training.module.workforce": "Nhân sự & đồng hồ chấm công",
  "training.newForYou": "Đào tạo mới cho bạn",
  "training.newForYouHelp": "Các bài học này được thêm vì vai trò của bạn mở rộng, hoặc ai đó đã giao chúng cho bạn. Hãy hoàn thành chúng để học các phần mới của ứng dụng.",
  "training.noDue": "Không có hạn chót",
