  "auth.sameEmailNotice": "Bạn đã có ứng dụng của chúng tôi từ Google Play hoặc App Store? Hãy dùng cùng một email tại đây — email bạn đăng nhập vào ứng dụng — để cửa hàng và hàng tồn kho của bạn đi cùng bạn. Một email khác sẽ bắt đầu một cửa hàng hoàn toàn mới, trống rỗng.",
