  "rewards.status.redeemed": "Đã dùng",
  "rewards.status.void": "Đã hủy bỏ hiệu lực",
  "rewards.subtitle": "Nói lời cảm ơn bằng một phần thưởng — giảm phần trăm, thẻ quà tặng, hoặc bất cứ điều gì bạn mô tả.",
  "rewards.title": "Phần thưởng & ưu đãi",
  "rewards.value.giftCard": "Thẻ quà tặng {value}",
  "rewards.value.percentOff": "Giảm {percent}% tại cửa hàng",
  "rewards.void": "Hủy bỏ hiệu lực",
  "rewards.voided": "Đã hủy bỏ hiệu lực phần thưởng.",
  "workforce.tab.rewards": "Phần thưởng",
  "training.lessons.mgr-give-rewards.step1": "Mở Nhân sự và chạm Phần thưởng. Chọn thành viên trong nhóm, sau đó chọn loại: giảm phần trăm tại cửa hàng, thẻ quà tặng, hoặc thứ khác bạn mô tả bằng lời của bạn.",
  "training.lessons.mgr-give-rewards.step2": "Đặt cho phần thưởng một tên ngắn và một ghi chú nếu bạn thích. Người đó nhận được một tiếng chuông ngay lập tức, và phần thưởng chờ trong Phần thưởng của tôi của họ với mã riêng của nó.",
  "training.lessons.mgr-give-rewards.step3": "Ranh giới, theo thiết kế: bạn chỉ thưởng cho NHÂN VIÊN. Bạn không thể thưởng cho chính mình hoặc một quản lý khác — việc thưởng cho quản lý là quyết định của chủ sở hữu, và ứng dụng sẽ từ chối rõ ràng.",
  "training.lessons.mgr-give-rewards.step4": "Tại quầy thu ngân, nhập mã mà thành viên trong nhóm cho bạn xem và đánh dấu đã dùng — mỗi mã chỉ hoạt động một lần. Bạn có thể hủy bỏ hiệu lực một phần thưởng bạn đã trao nếu kế hoạch thay đổi; quà tặng của chủ sở hữu thuộc về chủ sở hữu để hủy bỏ.",
  "training.lessons.mgr-give-rewards.title": "Trao phần thưởng cho nhân viên của bạn",
  "training.lessons.owner-give-rewards.step1": "Phần thưởng nằm trong Nhân sự, trên tab Phần thưởng, và chúng chỉ dành cho gói Business — trên Essentials, tab hiển thị một cánh cửa bị khóa, để nhóm của bạn có thể xem gói lớn hơn có gì.",
  "training.lessons.owner-give-rewards.step2": "Bạn có thể thưởng cho BẤT CỨ AI trong nhóm — nhân viên và quản lý như nhau. Chọn người, sau đó chọn loại: giảm phần trăm tại cửa hàng (bất kỳ phần trăm nào bạn chọn), thẻ quà tặng đến bất cứ đâu, hoặc bất kỳ ưu đãi nào bạn mô tả bằng lời của bạn.",
  "training.lessons.owner-give-rewards.step3": "Phần thưởng đến với mã dùng một lần riêng của nó và rung chuông của người đó. Họ cho xem mã tại quầy thu ngân; một chủ sở hữu hoặc quản lý nhập nó vào để đánh dấu đã dùng.",
  "training.lessons.owner-give-rewards.step4": "Một phiếu phần thưởng in hoặc chia sẻ chỉ mang tên doanh nghiệp của BẠN — không bao giờ là của ứng dụng. Đó là lời cảm ơn của cửa hàng bạn, không phải quảng cáo.",
  "training.lessons.owner-give-rewards.title": "Trao phần thưởng (gói Business)",
  "training.lessons.owner-rewards-oversight.step1": "Quản lý của bạn cũng có thể trao phần thưởng — chỉ cho nhân viên. Ứng dụng từ chối một quản lý tự thưởng cho mình hoặc thưởng cho một quản lý khác; việc thưởng cho quản lý luôn là quyết định của bạn.",
  "training.lessons.owner-rewards-oversight.step2": "Bạn xem mọi phần thưởng trong doanh nghiệp trong Lịch sử phần thưởng: ai đã trao nó, ai nhận được nó, và nó đã sẵn sàng, đã dùng hay đã hủy bỏ hiệu lực. Một quản lý chỉ xem các phần thưởng họ đã trao và những phần họ đã nhận.",
  "training.lessons.owner-rewards-oversight.step3": "Bạn có thể hủy bỏ hiệu lực bất kỳ phần thưởng nào, bao gồm một phần thưởng quản lý của bạn đã trao. Một quản lý có thể hủy bỏ hiệu lực quà tặng của chính họ, nhưng không bao giờ là của bạn.",
  "training.lessons.owner-rewards-oversight.step4": "Mỗi mã chỉ hoạt động đúng một lần, và một phần thưởng đã bị hủy bỏ hiệu lực không bao giờ có thể dùng — lịch sử luôn cho thấy một phần thưởng kết thúc theo cách nào.",
  "training.lessons.owner-rewards-oversight.title": "Giám sát phần thưởng: việc trao của quản lý bạn",
  "training.lessons.staff-your-rewards.step1": "Khi quản lý hoặc chủ sở hữu trao cho bạn một phần thưởng, chuông của bạn rung. Mở Nhân sự và chạm Phần thưởng để xem nó trong Phần thưởng của tôi.",
  "training.lessons.staff-your-rewards.step2": "Mọi phần thưởng đều có mã riêng của nó. Hãy giữ nó cho riêng mình — ai cho xem mã tại quầy thu ngân là người dùng phần thưởng đó.",
  "training.lessons.staff-your-rewards.step3": "Để dùng nó, hãy cho xem mã khi bạn mua hàng. Người ở quầy thu ngân nhập nó vào và đánh dấu đã dùng — mỗi mã chỉ hoạt động đúng một lần.",
  "training.lessons.staff-your-rewards.step4": "Phần thưởng là một món quà của gói Business. Nếu cửa hàng của bạn không dùng Business, tab Phần thưởng hiển thị một cánh cửa bị khóa thay thế — đó là gói, không phải lỗi.",
  "training.lessons.staff-your-rewards.title": "Phần thưởng của bạn: tìm mã và dùng nó",
  "training.module.rewards": "Phần thưởng & ưu đãi",
